"""
Job Status Tracking & Event Streaming

Provides real-time status tracking for orchestrator jobs with
SSE (Server-Sent Events) support for the GUI layer.
"""

from __future__ import annotations

import json
import logging
import threading
import time
from collections import defaultdict
from datetime import datetime
from typing import Any, Callable, Dict, List, Optional

from orchestrator.models import (
    Job,
    JobState,
    JobStatus,
    WorkerResult,
)

logger = logging.getLogger(__name__)


class StatusEvent:
    """A single status event for SSE streaming."""

    def __init__(self, job_id: str, event_type: str, data: Dict[str, Any]):
        self.job_id = job_id
        self.event_type = event_type
        self.data = data
        self.timestamp = datetime.utcnow().isoformat()

    def to_sse(self) -> str:
        """Format as Server-Sent Event string."""
        payload = {
            "job_id": self.job_id,
            "event": self.event_type,
            "data": self.data,
            "timestamp": self.timestamp,
        }
        return f"data: {json.dumps(payload)}\n\n"

    def to_dict(self) -> Dict[str, Any]:
        return {
            "job_id": self.job_id,
            "event": self.event_type,
            "data": self.data,
            "timestamp": self.timestamp,
        }


class JobTracker:
    """Thread-safe job status tracker with event history and SSE support."""

    def __init__(self, max_events_per_job: int = 500):
        self._lock = threading.Lock()
        self._jobs: Dict[str, Job] = {}
        self._statuses: Dict[str, JobStatus] = {}
        self._events: Dict[str, List[StatusEvent]] = defaultdict(list)
        self._subscribers: Dict[str, List[Callable[[StatusEvent], None]]] = defaultdict(list)
        self._max_events = max_events_per_job

    def register_job(self, job: Job) -> None:
        """Register a new job for tracking."""
        with self._lock:
            self._jobs[job.id] = job
            self._statuses[job.id] = JobStatus(
                job_id=job.id,
                state=job.state,
                steps_total=len(job.workflow.steps) if job.workflow else 0,
            )
        self._emit(job.id, "job.registered", {"goal": job.goal, "state": job.state.value})

    def update_state(self, job_id: str, state: JobState) -> None:
        """Update the overall job state."""
        with self._lock:
            if job_id in self._jobs:
                self._jobs[job_id].state = state
                self._jobs[job_id].updated_at = datetime.utcnow()
            if job_id in self._statuses:
                self._statuses[job_id].state = state
        self._emit(job_id, "job.state_changed", {"state": state.value})

    def update_step(self, job_id: str, step_id: str, event: str, result: Optional[WorkerResult] = None) -> None:
        """Update a specific step's status."""
        with self._lock:
            status = self._statuses.get(job_id)
            if status:
                status.current_step = step_id
                if result:
                    status.step_results.append(result)
                    if result.status.value == "completed":
                        status.steps_completed += 1
                    status.total_tokens += result.tokens_used

        data: Dict[str, Any] = {"step_id": step_id, "event": event}
        if result:
            data["agent_name"] = result.agent_name
            data["status"] = result.status.value
            data["duration"] = result.duration_seconds
        self._emit(job_id, f"step.{event}", data)

    def complete_job(self, job_id: str, final_output: str, state: JobState = JobState.COMPLETED) -> None:
        """Mark a job as completed with final output."""
        with self._lock:
            if job_id in self._jobs:
                self._jobs[job_id].state = state
                self._jobs[job_id].completed_at = datetime.utcnow()
            if job_id in self._statuses:
                self._statuses[job_id].state = state
                self._statuses[job_id].final_output = final_output
        self._emit(job_id, "job.completed", {"state": state.value, "output_length": len(final_output)})

    def get_status(self, job_id: str) -> Optional[JobStatus]:
        """Get the current status of a job."""
        with self._lock:
            return self._statuses.get(job_id)

    def get_job(self, job_id: str) -> Optional[Job]:
        """Get a job by ID."""
        with self._lock:
            return self._jobs.get(job_id)

    def list_jobs(self, state: Optional[JobState] = None) -> List[Job]:
        """List all tracked jobs, optionally filtered by state."""
        with self._lock:
            jobs = list(self._jobs.values())
        if state:
            jobs = [j for j in jobs if j.state == state]
        return sorted(jobs, key=lambda j: j.created_at, reverse=True)

    def get_events(self, job_id: str, since: int = 0) -> List[StatusEvent]:
        """Get events for a job since a given index."""
        with self._lock:
            events = self._events.get(job_id, [])
            return events[since:]

    def subscribe(self, job_id: str, callback: Callable[[StatusEvent], None]) -> Callable:
        """Subscribe to events for a job. Returns an unsubscribe function."""
        with self._lock:
            self._subscribers[job_id].append(callback)

        def unsubscribe():
            with self._lock:
                try:
                    self._subscribers[job_id].remove(callback)
                except ValueError:
                    pass

        return unsubscribe

    def _emit(self, job_id: str, event_type: str, data: Dict[str, Any]) -> None:
        """Emit an event to all subscribers and store in history."""
        event = StatusEvent(job_id, event_type, data)

        with self._lock:
            events = self._events[job_id]
            events.append(event)
            if len(events) > self._max_events:
                self._events[job_id] = events[-self._max_events:]
            subscribers = list(self._subscribers.get(job_id, []))

        for callback in subscribers:
            try:
                callback(event)
            except Exception as e:
                logger.warning("Event subscriber error: %s", e)


# Global singleton
_tracker: Optional[JobTracker] = None


def get_tracker() -> JobTracker:
    """Get the global JobTracker singleton."""
    global _tracker
    if _tracker is None:
        _tracker = JobTracker()
    return _tracker

"""
Roster Configuration — loads and manages _defaults.yaml for model assignments.
"""

from __future__ import annotations

import logging
from pathlib import Path
from typing import Any, Dict, Optional

import yaml

logger = logging.getLogger(__name__)

_DEFAULTS_PATH = Path(__file__).parent.parent / "agency_roster" / "_defaults.yaml"


def load_roster_defaults(path: Optional[Path] = None) -> Dict[str, Any]:
    """Load the roster defaults configuration."""
    filepath = path or _DEFAULTS_PATH
    if not filepath.exists():
        return {}
    try:
        with open(filepath, encoding="utf-8") as f:
            return yaml.safe_load(f) or {}
    except Exception as e:
        logger.warning("Failed to load roster defaults: %s", e)
        return {}


def get_division_model(division: str, defaults: Optional[Dict] = None) -> Optional[str]:
    """Get the default model for a specific division."""
    if defaults is None:
        defaults = load_roster_defaults()
    return defaults.get("divisions", {}).get(division, {}).get("default_model")


def get_global_model(defaults: Optional[Dict] = None) -> str:
    """Get the global default model."""
    if defaults is None:
        defaults = load_roster_defaults()
    return defaults.get("global_default_model", "anthropic/claude-sonnet-4-20250514")

"""
Agent Roster — loader and registry for agency_roster/ Markdown definitions.

Parses YAML frontmatter + Markdown body from each agent .md file into
AgentDefinition objects. Provides search, filtering, and summary generation
for the orchestrator Manager.
"""

from __future__ import annotations

import logging
import os
import re
from pathlib import Path
from typing import Dict, List, Optional

import yaml

from orchestrator.models import AgentDefinition

logger = logging.getLogger(__name__)

# Default roster directory relative to project root
_DEFAULT_ROSTER_DIR = Path(__file__).parent.parent / "agency_roster"

# Frontmatter regex: matches --- ... --- at the start of a file
_FRONTMATTER_RE = re.compile(r"^---\s*\n(.*?)\n---\s*\n", re.DOTALL)


def _parse_agent_file(filepath: Path) -> Optional[AgentDefinition]:
    """Parse a single agent Markdown file into an AgentDefinition."""
    try:
        content = filepath.read_text(encoding="utf-8")
    except Exception as e:
        logger.warning("Failed to read agent file %s: %s", filepath, e)
        return None

    # Extract YAML frontmatter
    frontmatter: Dict = {}
    body = content
    match = _FRONTMATTER_RE.match(content)
    if match:
        try:
            frontmatter = yaml.safe_load(match.group(1)) or {}
        except yaml.YAMLError as e:
            logger.warning("Bad YAML frontmatter in %s: %s", filepath, e)
        body = content[match.end():]

    # Derive division from parent directory name
    division = filepath.parent.name

    # Build AgentDefinition from frontmatter + body
    return AgentDefinition(
        name=frontmatter.get("name", filepath.stem.replace("_", " ").title()),
        emoji=frontmatter.get("emoji", ""),
        division=frontmatter.get("division", division),
        specialty=frontmatter.get("specialty", ""),
        use_case=frontmatter.get("use_case", ""),
        default_model=frontmatter.get(
            "default_model", "anthropic/claude-sonnet-4-20250514"
        ),
        tags=frontmatter.get("tags", []),
        system_prompt=body.strip(),
        source_file=str(filepath),
        role=frontmatter.get("role", "worker"),
    )


class AgentRoster:
    """Registry of all available agent definitions loaded from agency_roster/."""

    def __init__(self) -> None:
        self._agents: Dict[str, AgentDefinition] = {}  # keyed by normalized name
        self._by_division: Dict[str, List[AgentDefinition]] = {}

    @staticmethod
    def _normalize_name(name: str) -> str:
        """Normalize agent name for lookup (lowercase, stripped)."""
        return name.lower().strip()

    def load(self, roster_dir: Optional[Path] = None) -> int:
        """Load all agent .md files from roster_dir. Returns count loaded."""
        roster_dir = Path(roster_dir or _DEFAULT_ROSTER_DIR)
        if not roster_dir.is_dir():
            logger.warning("Roster directory not found: %s", roster_dir)
            return 0

        count = 0
        for md_file in sorted(roster_dir.rglob("*.md")):
            # Skip _defaults.yaml and other non-agent files
            if md_file.name.startswith("_"):
                continue
            agent = _parse_agent_file(md_file)
            if agent:
                key = self._normalize_name(agent.name)
                self._agents[key] = agent
                self._by_division.setdefault(agent.division, []).append(agent)
                count += 1
                logger.debug("Loaded agent: %s (%s)", agent.name, agent.division)

        logger.info("Loaded %d agents from %s", count, roster_dir)
        return count

    def get_agent(self, name: str) -> Optional[AgentDefinition]:
        """Get an agent by exact name (case-insensitive)."""
        return self._agents.get(self._normalize_name(name))

    def search(self, query: str, top_k: int = 10) -> List[AgentDefinition]:
        """Search agents by relevance to a query string."""
        scored = [
            (agent, agent.match_score(query))
            for agent in self._agents.values()
        ]
        scored.sort(key=lambda x: x[1], reverse=True)
        return [agent for agent, score in scored[:top_k] if score > 0.0]

    def list_division(self, division: str) -> List[AgentDefinition]:
        """List all agents in a specific division."""
        return self._by_division.get(division, [])

    def list_all(self) -> List[AgentDefinition]:
        """List all loaded agents."""
        return list(self._agents.values())

    def list_divisions(self) -> List[str]:
        """List all division names."""
        return sorted(self._by_division.keys())

    def get_roster_summary(self) -> str:
        """Generate a compact text summary for the Manager's system prompt context."""
        lines = []
        for division in sorted(self._by_division.keys()):
            agents = self._by_division[division]
            div_display = division.replace("_", " ").title()
            lines.append(f"\n## {div_display} Division ({len(agents)} agents)")
            for agent in agents:
                use = f" | Use: {agent.use_case}" if agent.use_case else ""
                lines.append(f"  - {agent.emoji} {agent.name}: {agent.specialty}{use}")
        return "\n".join(lines)

    def __len__(self) -> int:
        return len(self._agents)

    def __contains__(self, name: str) -> bool:
        return self._normalize_name(name) in self._agents

"""
Manager-specific tools — registered in the Hermes tool system.

These tools give the Orchestrator Manager agent the ability to:
  - query_roster: Search the agency roster for the best agent
  - create_workflow: Build and execute a workflow DAG
  - spawn_single_agent: Quick single-agent delegation
  - check_workflow_status: Poll a running workflow
"""

from __future__ import annotations

import json
import logging
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)

# These will be set at initialization by the manager
_roster = None
_mal = None
_engine = None
_tracker = None


def init_manager_tools(roster, mal, engine, tracker):
    """Initialize manager tools with dependencies."""
    global _roster, _mal, _engine, _tracker
    _roster = roster
    _mal = mal
    _engine = engine
    _tracker = tracker


def check_orchestrator_requirements() -> bool:
    """Check if orchestrator tools are available."""
    return _roster is not None and len(_roster) > 0


# ---------------------------------------------------------------------------
# Tool: query_roster
# ---------------------------------------------------------------------------

QUERY_ROSTER_SCHEMA = {
    "type": "function",
    "function": {
        "name": "query_roster",
        "description": (
            "Search the Agency Roster for specialized agents. Returns agents "
            "matching the query, ranked by relevance. Use this to find the best "
            "agent for a sub-task before creating a workflow."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "query": {
                    "type": "string",
                    "description": "Search query (e.g., 'frontend react ui', 'database optimization', 'marketing strategy')",
                },
                "division": {
                    "type": "string",
                    "description": "Optional: filter by division (engineering, design, marketing, sales, etc.)",
                },
                "top_k": {
                    "type": "integer",
                    "description": "Max results to return (default: 5)",
                    "default": 5,
                },
            },
            "required": ["query"],
        },
    },
}


async def query_roster(query: str, division: str = None, top_k: int = 5) -> str:
    """Search the roster for matching agents."""
    if not _roster:
        return "Error: Agent roster not loaded."

    if division:
        agents = _roster.list_division(division)
        # Filter by query within division
        scored = [(a, a.match_score(query)) for a in agents]
        scored.sort(key=lambda x: x[1], reverse=True)
        results = [a for a, s in scored[:top_k] if s > 0.0]
    else:
        results = _roster.search(query, top_k=top_k)

    if not results:
        return f"No agents found matching '{query}'. Try broader terms."

    lines = [f"Found {len(results)} matching agents:\n"]
    for agent in results:
        lines.append(
            f"- {agent.emoji} **{agent.name}** [{agent.division}]\n"
            f"  Specialty: {agent.specialty}\n"
            f"  Use: {agent.use_case}\n"
            f"  Default model: {agent.default_model}"
        )
    return "\n".join(lines)


# ---------------------------------------------------------------------------
# Tool: create_workflow
# ---------------------------------------------------------------------------

CREATE_WORKFLOW_SCHEMA = {
    "type": "function",
    "function": {
        "name": "create_workflow",
        "description": (
            "Create and execute a multi-step workflow DAG. Each step assigns "
            "a task to a specific agent from the roster. Steps can run in "
            "parallel (no dependencies) or sequentially (with depends_on). "
            "Use {prev_result} or {step_<id>_result} in task templates to "
            "reference prior step outputs."
        ),
        "parameters": {
            "type": "object",
            "properties": {
                "name": {
                    "type": "string",
                    "description": "Human-readable workflow name",
                },
                "steps": {
                    "type": "array",
                    "description": "Ordered list of workflow steps",
                    "items": {
                        "type": "object",
                        "properties": {
                            "id": {
