"""
REST API for the Orchestrator — enables Hermes-Workspace GUI integration.

Provides endpoints for job submission, status polling, roster browsing,
and SSE event streaming. Designed to be mounted on the existing
Hermes gateway HTTP server.
"""

from __future__ import annotations

import asyncio
import json
import logging
import threading
import time
from typing import Any, Dict, List, Optional

logger = logging.getLogger(__name__)

# Lazy-initialized singleton
_manager = None


def _get_manager():
    """Get or create the OrchestratorManager singleton."""
    global _manager
    if _manager is None:
        from orchestrator.manager import OrchestratorManager
        _manager = OrchestratorManager()
    return _manager


def _get_tracker():
    """Get the global JobTracker."""
    from orchestrator.status import get_tracker
    return get_tracker()


# ---------------------------------------------------------------------------
# Request/Response helpers
# ---------------------------------------------------------------------------

def _json_response(data: Any, status: int = 200) -> Dict[str, Any]:
    """Build a JSON response dict."""
    return {"status": status, "body": data}


def _error_response(message: str, status: int = 400) -> Dict[str, Any]:
    """Build an error response dict."""
    return {"status": status, "body": {"error": message}}


# ---------------------------------------------------------------------------
# API Handlers (called by gateway or standalone server)
# ---------------------------------------------------------------------------

def handle_submit_job(body: Dict[str, Any]) -> Dict[str, Any]:
    """POST /api/orchestrator/jobs — Submit a new orchestration job."""
    goal = body.get("goal")
    if not goal:
        return _error_response("Missing required field: 'goal'")

    manager = _get_manager()

    # Parse optional workflow
    workflow = None
    if body.get("workflow"):
        from orchestrator.models import WorkflowDAG, WorkflowStep
        try:
            steps_data = body["workflow"].get("steps", [])
            steps = [WorkflowStep(**s) for s in steps_data]
            workflow = WorkflowDAG(
                name=body["workflow"].get("name", goal[:50]),
                steps=steps,
            )
        except Exception as e:
            return _error_response(f"Invalid workflow: {e}")

    # Submit the job
    job = manager.submit_job(
        goal=goal,
        workflow=workflow,
        model_override=body.get("model_override"),
        context=body.get("context", {}),
        schedule=body.get("schedule"),
    )

    # Handle scheduled jobs
    if job.schedule:
        from orchestrator.scheduler import OrchestratorScheduler
        scheduler = OrchestratorScheduler()
        schedule_id = scheduler.schedule_workflow(
            name=goal[:50],
            goal=goal,
            cron_expression=job.schedule,
            model_override=body.get("model_override"),
            context=body.get("context"),
        )
        return _json_response({
            "job_id": job.id,
            "state": "scheduled",
            "schedule_id": schedule_id,
            "schedule": job.schedule,
        }, 201)

    # Execute in background thread
    def _run():
        manager.execute_job(job)

    thread = threading.Thread(target=_run, name=f"orchestrator-job-{job.id}", daemon=True)
    thread.start()

    return _json_response({
        "job_id": job.id,
        "state": job.state.value,
        "message": "Job submitted and executing",
    }, 201)


def handle_get_job(job_id: str) -> Dict[str, Any]:
    """GET /api/orchestrator/jobs/{id} — Get job status and results."""
    tracker = _get_tracker()
    status = tracker.get_status(job_id)
    if not status:
        return _error_response(f"Job '{job_id}' not found", 404)

    return _json_response({
        "job_id": status.job_id,
        "state": status.state.value,
        "current_step": status.current_step,
        "steps_completed": status.steps_completed,
        "steps_total": status.steps_total,
        "elapsed_seconds": status.elapsed_seconds,
        "total_tokens": status.total_tokens,
        "step_results": [
            {
                "step_id": r.step_id,
                "agent_name": r.agent_name,
                "status": r.status.value,
                "output": r.output[:1000] if r.output else None,
                "error": r.error,
                "duration_seconds": r.duration_seconds,
                "model_used": r.model_used,
            }
            for r in status.step_results
        ],
        "final_output": status.final_output,
    })


def handle_list_jobs(state: Optional[str] = None) -> Dict[str, Any]:
    """GET /api/orchestrator/jobs — List all jobs."""
    tracker = _get_tracker()

    state_filter = None
    if state:
        from orchestrator.models import JobState
        try:
            state_filter = JobState(state)
        except ValueError:
            return _error_response(f"Invalid state: {state}")

    jobs = tracker.list_jobs(state=state_filter)
    return _json_response({
        "jobs": [
            {
                "id": j.id,
                "goal": j.goal[:200],
                "state": j.state.value,
                "created_at": j.created_at.isoformat() if j.created_at else None,
            }
            for j in jobs
        ],
        "total": len(jobs),
    })


def handle_cancel_job(job_id: str) -> Dict[str, Any]:
    """DELETE /api/orchestrator/jobs/{id} — Cancel a running job."""
    tracker = _get_tracker()
    job = tracker.get_job(job_id)
    if not job:
        return _error_response(f"Job '{job_id}' not found", 404)

    from orchestrator.models import JobState
    tracker.update_state(job_id, JobState.CANCELLED)
    return _json_response({"job_id": job_id, "state": "cancelled"})


def handle_list_roster(division: Optional[str] = None) -> Dict[str, Any]:
    """GET /api/orchestrator/roster — List all agents."""
    manager = _get_manager()

    if division:
        agents = manager.roster.list_division(division)
    else:
        agents = manager.roster.list_all()

    return _json_response({
        "agents": [
            {
                "name": a.name,
                "emoji": a.emoji,
                "division": a.division,
                "specialty": a.specialty,
                "use_case": a.use_case,
                "default_model": a.default_model,
                "tags": a.tags,
                "role": a.role,
            }
            for a in agents
        ],
        "total": len(agents),
        "divisions": manager.roster.list_divisions(),
    })


def handle_get_agent(agent_name: str) -> Dict[str, Any]:
    """GET /api/orchestrator/roster/{name} — Get agent details."""
    manager = _get_manager()
    agent = manager.roster.get_agent(agent_name)
    if not agent:
        return _error_response(f"Agent '{agent_name}' not found", 404)

    return _json_response({
        "name": agent.name,
        "emoji": agent.emoji,
        "division": agent.division,
        "specialty": agent.specialty,
        "use_case": agent.use_case,
        "default_model": agent.default_model,
        "tags": agent.tags,
        "role": agent.role,
        "system_prompt": agent.system_prompt,
        "source_file": agent.source_file,
    })


def handle_search_roster(query: str, top_k: int = 10) -> Dict[str, Any]:
    """GET /api/orchestrator/roster/search?q=... — Search agents."""
    manager = _get_manager()
    results = manager.roster.search(query, top_k=top_k)

    return _json_response({
        "query": query,
        "results": [
            {
                "name": a.name,
                "emoji": a.emoji,
                "division": a.division,
                "specialty": a.specialty,
                "use_case": a.use_case,
                "score": a.match_score(query),
            }
            for a in results
        ],
        "total": len(results),
    })


def handle_sse_stream(job_id: str):
    """GET /api/orchestrator/status/stream?job_id=... — SSE event stream.

    Returns a generator of SSE-formatted strings for real-time updates.
    """
    tracker = _get_tracker()
    event_queue = []
    done = threading.Event()

    def _on_event(event):
        event_queue.append(event)
        if event.event_type in ("job.completed", "job.failed"):
            done.set()

    unsubscribe = tracker.subscribe(job_id, _on_event)

    def _generate():
        try:
            # Send existing events first
            for event in tracker.get_events(job_id):
                yield event.to_sse()

            # Stream new events
            while not done.is_set():
                while event_queue:
                    event = event_queue.pop(0)
                    yield event.to_sse()
                time.sleep(0.5)

            # Flush remaining
            while event_queue:
                yield event_queue.pop(0).to_sse()

        finally:
            unsubscribe()

    return _generate()


# ---------------------------------------------------------------------------
# Route table for integration with gateway/run.py
# ---------------------------------------------------------------------------

ORCHESTRATOR_ROUTES = {
    ("POST", "/api/orchestrator/jobs"): handle_submit_job,
    ("GET", "/api/orchestrator/jobs"): handle_list_jobs,
    ("GET", "/api/orchestrator/jobs/{id}"): handle_get_job,
    ("DELETE", "/api/orchestrator/jobs/{id}"): handle_cancel_job,
    ("GET", "/api/orchestrator/roster"): handle_list_roster,
    ("GET", "/api/orchestrator/roster/search"): handle_search_roster,
    ("GET", "/api/orchestrator/roster/{name}"): handle_get_agent,
    ("GET", "/api/orchestrator/status/stream"): handle_sse_stream,
}

# nix/python.nix — uv2nix virtual environment builder
{
  python311,
  lib,
  callPackage,
  uv2nix,
  pyproject-nix,
  pyproject-build-systems,
  stdenv,
}:
let
  workspace = uv2nix.lib.workspace.loadWorkspace { workspaceRoot = ./..; };
  hacks = callPackage pyproject-nix.build.hacks { };

  overlay = workspace.mkPyprojectOverlay {
    sourcePreference = "wheel";
  };

  isAarch64Darwin = stdenv.hostPlatform.system == "aarch64-darwin";

  # Keep the workspace locked through uv2nix, but supply the local voice stack
  # from nixpkgs so wheel-only transitive artifacts do not break evaluation.
  mkPrebuiltPassthru = dependencies: {
    inherit dependencies;
    optional-dependencies = { };
    dependency-groups = { };
  };

  mkPrebuiltOverride = final: from: dependencies:
    hacks.nixpkgsPrebuilt {
      inherit from;
      prev = {
        nativeBuildInputs = [ final.pyprojectHook ];
        passthru = mkPrebuiltPassthru dependencies;
      };
    };

  pythonPackageOverrides = final: _prev:
    if isAarch64Darwin then {
      numpy = mkPrebuiltOverride final python311.pkgs.numpy { };

      av = mkPrebuiltOverride final python311.pkgs.av { };

      humanfriendly = mkPrebuiltOverride final python311.pkgs.humanfriendly { };

      coloredlogs = mkPrebuiltOverride final python311.pkgs.coloredlogs {
        humanfriendly = [ ];
      };

      onnxruntime = mkPrebuiltOverride final python311.pkgs.onnxruntime {
        coloredlogs = [ ];
        numpy = [ ];
        packaging = [ ];
      };

      ctranslate2 = mkPrebuiltOverride final python311.pkgs.ctranslate2 {
        numpy = [ ];
        pyyaml = [ ];
      };

      faster-whisper = mkPrebuiltOverride final python311.pkgs.faster-whisper {
        av = [ ];
        ctranslate2 = [ ];
        huggingface-hub = [ ];
        onnxruntime = [ ];
        tokenizers = [ ];
        tqdm = [ ];
      };
    } else {};

  pythonSet =
    (callPackage pyproject-nix.build.packages {
      python = python311;
    }).overrideScope
      (lib.composeManyExtensions [
        pyproject-build-systems.overlays.default
        overlay
        pythonPackageOverrides
      ]);
in
pythonSet.mkVirtualEnv "hermes-agent-env" {
  hermes-agent = [ "all" ];
}

# nix/packages.nix — Hermes Agent package built with uv2nix
{ inputs, ... }: {
  perSystem = { pkgs, system, ... }:
    let
      hermesVenv = pkgs.callPackage ./python.nix {
        inherit (inputs) uv2nix pyproject-nix pyproject-build-systems;
      };

      # Import bundled skills, excluding runtime caches
      bundledSkills = pkgs.lib.cleanSourceWith {
        src = ../skills;
        filter = path: _type:
          !(pkgs.lib.hasInfix "/index-cache/" path);
      };

      runtimeDeps = with pkgs; [
        nodejs_20 ripgrep git openssh ffmpeg tirith
      ];

      runtimePath = pkgs.lib.makeBinPath runtimeDeps;
    in {
      packages.default = pkgs.stdenv.mkDerivation {
        pname = "hermes-agent";
        version = (builtins.fromTOML (builtins.readFile ../pyproject.toml)).project.version;

        dontUnpack = true;
        dontBuild = true;
        nativeBuildInputs = [ pkgs.makeWrapper ];

        installPhase = ''
          runHook preInstall

          mkdir -p $out/share/hermes-agent $out/bin
          cp -r ${bundledSkills} $out/share/hermes-agent/skills

          ${pkgs.lib.concatMapStringsSep "\n" (name: ''
            makeWrapper ${hermesVenv}/bin/${name} $out/bin/${name} \
              --suffix PATH : "${runtimePath}" \
              --set HERMES_BUNDLED_SKILLS $out/share/hermes-agent/skills
          '') [ "hermes" "hermes-agent" "hermes-acp" ]}

          runHook postInstall
        '';

        meta = with pkgs.lib; {
          description = "AI agent with advanced tool-calling capabilities";
          homepage = "https://github.com/NousResearch/hermes-agent";
          mainProgram = "hermes";
          license = licenses.mit;
          platforms = platforms.unix;
        };
      };
    };
}

# nix/nixosModules.nix — NixOS module for hermes-agent
#
# Two modes:
#   container.enable = false (default) → native systemd service
#   container.enable = true            → OCI container (persistent writable layer)
#
# Container mode: hermes runs from /nix/store bind-mounted read-only into a
# plain Ubuntu container. The writable layer (apt/pip/npm installs) persists
# across restarts and agent updates. Only image/volume/options changes trigger
# container recreation. Environment variables are written to $HERMES_HOME/.env
# and read by hermes at startup — no container recreation needed for env changes.
#
# Tool resolution: the hermes wrapper uses --suffix PATH for nix store tools,
# so apt/uv-installed versions take priority. The container entrypoint provisions
# extensible tools on first boot: nodejs/npm via apt, uv via curl, and a Python
# 3.11 venv (bootstrapped entirely by uv) at ~/.venv with pip seeded. Agents get
# writable tool prefixes for npm i -g, pip install, uv tool install, etc.
#
# Usage:
#   services.hermes-agent = {
#     enable = true;
#     settings.model = "anthropic/claude-sonnet-4";
#     environmentFiles = [ config.sops.secrets."hermes/env".path ];
#   };
#
{ inputs, ... }: {
  flake.nixosModules.default = { config, lib, pkgs, ... }:

  let
    cfg = config.services.hermes-agent;
    hermes-agent = inputs.self.packages.${pkgs.system}.default;

    # Deep-merge config type (from 0xrsydn/nix-hermes-agent)
    deepConfigType = lib.types.mkOptionType {
      name = "hermes-config-attrs";
      description = "Hermes YAML config (attrset), merged deeply via lib.recursiveUpdate.";
      check = builtins.isAttrs;
      merge = _loc: defs: lib.foldl' lib.recursiveUpdate { } (map (d: d.value) defs);
    };

    # Generate config.yaml from Nix attrset (YAML is a superset of JSON)
    configJson = builtins.toJSON cfg.settings;
    generatedConfigFile = pkgs.writeText "hermes-config.yaml" configJson;
    configFile = if cfg.configFile != null then cfg.configFile else generatedConfigFile;

    configMergeScript = pkgs.callPackage ./configMergeScript.nix { };

    # Generate .env from non-secret environment attrset
    envFileContent = lib.concatStringsSep "\n" (
      lib.mapAttrsToList (k: v: "${k}=${v}") cfg.environment
    );
    # Build documents derivation (from 0xrsydn)
    documentDerivation = pkgs.runCommand "hermes-documents" { } (
      ''
        mkdir -p $out
      '' + lib.concatStringsSep "\n" (
        lib.mapAttrsToList (name: value:
          if builtins.isPath value || lib.isStorePath value
          then "cp ${value} $out/${name}"
          else "cat > $out/${name} <<'HERMES_DOC_EOF'\n${value}\nHERMES_DOC_EOF"
        ) cfg.documents
      )
    );

    containerName = "hermes-agent";
    containerDataDir = "/data";     # stateDir mount point inside container
    containerHomeDir = "/home/hermes";

    # ── Container mode helpers ──────────────────────────────────────────
    containerBin = if cfg.container.backend == "docker"
      then "${pkgs.docker}/bin/docker"
      else "${pkgs.podman}/bin/podman";

    # Runs as root inside the container on every start. Provisions the
    # hermes user + sudo on first boot (writable layer persists), then
    # drops privileges. Supports arbitrary base images (Debian, Alpine, etc).
    containerEntrypoint = pkgs.writeShellScript "hermes-container-entrypoint" ''
      set -eu

      HERMES_UID="''${HERMES_UID:?HERMES_UID must be set}"
      HERMES_GID="''${HERMES_GID:?HERMES_GID must be set}"

      # ── Group: ensure a group with GID=$HERMES_GID exists ──
      # Check by GID (not name) to avoid collisions with pre-existing groups
      # (e.g. GID 100 = "users" on Ubuntu)
      EXISTING_GROUP=$(getent group "$HERMES_GID" 2>/dev/null | cut -d: -f1 || true)
      if [ -n "$EXISTING_GROUP" ]; then
        GROUP_NAME="$EXISTING_GROUP"
      else
        GROUP_NAME="hermes"
        if command -v groupadd >/dev/null 2>&1; then
          groupadd -g "$HERMES_GID" "$GROUP_NAME"
        elif command -v addgroup >/dev/null 2>&1; then
          addgroup -g "$HERMES_GID" "$GROUP_NAME" 2>/dev/null || true
        fi
      fi

      # ── User: ensure a user with UID=$HERMES_UID exists ──
      PASSWD_ENTRY=$(getent passwd "$HERMES_UID" 2>/dev/null || true)
      if [ -n "$PASSWD_ENTRY" ]; then
        TARGET_USER=$(echo "$PASSWD_ENTRY" | cut -d: -f1)
        TARGET_HOME=$(echo "$PASSWD_ENTRY" | cut -d: -f6)
      else
        TARGET_USER="hermes"
        TARGET_HOME="/home/hermes"
        if command -v useradd >/dev/null 2>&1; then
          useradd -u "$HERMES_UID" -g "$HERMES_GID" -m -d "$TARGET_HOME" -s /bin/bash "$TARGET_USER"
        elif command -v adduser >/dev/null 2>&1; then
          adduser -u "$HERMES_UID" -D -h "$TARGET_HOME" -s /bin/sh -G "$GROUP_NAME" "$TARGET_USER" 2>/dev/null || true
        fi
      fi
      mkdir -p "$TARGET_HOME"
      chown "$HERMES_UID:$HERMES_GID" "$TARGET_HOME"
      chmod 0750 "$TARGET_HOME"

      # Ensure HERMES_HOME is owned by the target user
      if [ -n "''${HERMES_HOME:-}" ] && [ -d "$HERMES_HOME" ]; then
        chown -R "$HERMES_UID:$HERMES_GID" "$HERMES_HOME"
      fi

      # ── Provision apt packages (first boot only, cached in writable layer) ──
      # sudo: agent self-modification
      # nodejs/npm: writable node so npm i -g works (nix store copies are read-only)
      # curl: needed for uv installer
      if [ ! -f /var/lib/hermes-tools-provisioned ] && command -v apt-get >/dev/null 2>&1; then
        echo "First boot: provisioning agent tools..."
        apt-get update -qq
        apt-get install -y -qq sudo nodejs npm curl
        touch /var/lib/hermes-tools-provisioned
      fi

      if command -v sudo >/dev/null 2>&1 && [ ! -f /etc/sudoers.d/hermes ]; then
        mkdir -p /etc/sudoers.d
        echo "$TARGET_USER ALL=(ALL) NOPASSWD:ALL" > /etc/sudoers.d/hermes
        chmod 0440 /etc/sudoers.d/hermes
      fi

      # uv (Python manager) — not in Ubuntu repos, retry-safe outside the sentinel
      if ! command -v uv >/dev/null 2>&1 && [ ! -x "$TARGET_HOME/.local/bin/uv" ] && command -v curl >/dev/null 2>&1; then
        su -s /bin/sh "$TARGET_USER" -c 'curl -LsSf https://astral.sh/uv/install.sh | sh' || true
      fi

      # Python 3.11 venv — gives the agent a writable Python with pip.
      # Uses uv to install Python 3.11 (Ubuntu 24.04 ships 3.12).
      # --seed includes pip/setuptools so bare `pip install` works.
      _UV_BIN="$TARGET_HOME/.local/bin/uv"
      if [ ! -d "$TARGET_HOME/.venv" ] && [ -x "$_UV_BIN" ]; then
        su -s /bin/sh "$TARGET_USER" -c "
          export PATH=\"\$HOME/.local/bin:\$PATH\"
          uv python install 3.11
          uv venv --python 3.11 --seed \"\$HOME/.venv\"
        " || true
      fi

      # Put the agent venv first on PATH so python/pip resolve to writable copies
      if [ -d "$TARGET_HOME/.venv/bin" ]; then
        export PATH="$TARGET_HOME/.venv/bin:$PATH"
      fi

      if command -v setpriv >/dev/null 2>&1; then
        exec setpriv --reuid="$HERMES_UID" --regid="$HERMES_GID" --init-groups "$@"
      elif command -v su >/dev/null 2>&1; then
        exec su -s /bin/sh "$TARGET_USER" -c 'exec "$0" "$@"' -- "$@"
      else
        echo "WARNING: no privilege-drop tool (setpriv/su), running as root" >&2
        exec "$@"
      fi
    '';

    # Identity hash — only recreate container when structural config changes.
    # Package and entrypoint use stable symlinks (current-package, current-entrypoint)
    # so they can update without recreation. Env vars go through $HERMES_HOME/.env.
    containerIdentity = builtins.hashString "sha256" (builtins.toJSON {
      schema = 3; # bump when identity inputs change
      image = cfg.container.image;
      extraVolumes = cfg.container.extraVolumes;
      extraOptions = cfg.container.extraOptions;
    });

    identityFile = "${cfg.stateDir}/.container-identity";

    # Default: /var/lib/hermes/workspace → /data/workspace.
    # Custom paths outside stateDir pass through unchanged (user must add extraVolumes).
    containerWorkDir =
      if lib.hasPrefix "${cfg.stateDir}/" cfg.workingDirectory
      then "${containerDataDir}/${lib.removePrefix "${cfg.stateDir}/" cfg.workingDirectory}"
      else cfg.workingDirectory;

  in {
    options.services.hermes-agent = with lib; {
      enable = mkEnableOption "Hermes Agent gateway service";

      # ── Package ──────────────────────────────────────────────────────────
      package = mkOption {
        type = types.package;
        default = hermes-agent;
        description = "The hermes-agent package to use.";
      };

      # ── Service identity ─────────────────────────────────────────────────
      user = mkOption {
        type = types.str;
        default = "hermes";
        description = "System user running the gateway.";
      };

      group = mkOption {
        type = types.str;
        default = "hermes";
        description = "System group running the gateway.";
      };

      createUser = mkOption {
        type = types.bool;
        default = true;
        description = "Create the user/group automatically.";
      };

      # ── Directories ──────────────────────────────────────────────────────
      stateDir = mkOption {
        type = types.str;
        default = "/var/lib/hermes";
        description = "State directory. Contains .hermes/ subdir (HERMES_HOME).";
      };

      workingDirectory = mkOption {
        type = types.str;
        default = "${cfg.stateDir}/workspace";
        defaultText = literalExpression ''"''${cfg.stateDir}/workspace"'';
        description = "Working directory for the agent (MESSAGING_CWD).";
      };

      # ── Declarative config ───────────────────────────────────────────────
      configFile = mkOption {
        type = types.nullOr types.path;
        default = null;
