/* =========================================================================
   Hermes Agent Landing Page
   Colors: Nous Blue (#3050FF) palette
   ========================================================================= */

/* --- Reset & Base --- */
*, *::before, *::after {
    margin: 0;
    padding: 0;
    box-sizing: border-box;
}

:root {
    --primary: #3050FF;
    --primary-light: #5070FF;
    --primary-dim: #2040CC;
    --primary-dark: #1E30AA;
    --bg: #0A0E1A;
    --bg-card: #12182A;
    --bg-card-hover: #1A2240;
    --border: rgba(48, 80, 255, 0.1);
    --border-hover: rgba(48, 80, 255, 0.22);
    --text: #E8ECFF;
    --text-dim: #8090BB;
    --text-muted: #506090;
    --font-sans: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', sans-serif;
    --font-mono: 'JetBrains Mono', 'Fira Code', 'Cascadia Code', monospace;
    --container: 1080px;
    --radius: 12px;
    --radius-sm: 8px;

    --ease-in-quad: cubic-bezier(.55, .085, .68, .53);
    --ease-in-cubic: cubic-bezier(.550, .055, .675, .19);
    --ease-in-quart: cubic-bezier(.895, .03, .685, .22);
    --ease-in-quint: cubic-bezier(.755, .05, .855, .06);
    --ease-in-expo: cubic-bezier(.95, .05, .795, .035);
    --ease-in-circ: cubic-bezier(.6, .04, .98, .335);

    --ease-out-quad: cubic-bezier(.25, .46, .45, .94);
    --ease-out-cubic: cubic-bezier(.215, .61, .355, 1);
    --ease-out-quart: cubic-bezier(.165, .84, .44, 1);
    --ease-out-quint: cubic-bezier(.23, 1, .32, 1);
    --ease-out-expo: cubic-bezier(.19, 1, .22, 1);
    --ease-out-circ: cubic-bezier(.075, .82, .165, 1);

    --ease-in-out-quad: cubic-bezier(.455, .03, .515, .955);
    --ease-in-out-cubic: cubic-bezier(.645, .045, .355, 1);
    --ease-in-out-quart: cubic-bezier(.77, 0, .175, 1);
    --ease-in-out-quint: cubic-bezier(.86, 0, .07, 1);
    --ease-in-out-expo: cubic-bezier(1, 0, 0, 1);
    --ease-in-out-circ: cubic-bezier(.785, .135, .15, .86);
}

html {
    scroll-behavior: smooth;
    -webkit-font-smoothing: antialiased;
    -moz-osx-font-smoothing: grayscale;
    overflow-x: hidden;
}

body {
    font-family: var(--font-sans);
    background: var(--bg);
    color: var(--text);
    line-height: 1.6;
    overflow-x: hidden;
    width: 100%;
    max-width: 100vw;
    background-image: radial-gradient(rgba(48, 80, 255, 0.04) 1px, transparent 1px);
    background-size: 32px 32px;
}

a {
    color: var(--primary);
    text-decoration: none;
    transition: color 0.2s var(--ease-out-quad);
}
a:hover {
    color: var(--primary-light);
}

strong {
    color: #fff;
    font-weight: 600;
}

/* --- Noise Overlay --- */
#noise-overlay {
    position: fixed;
    inset: 0;
    width: 100%;
    height: 100%;
    z-index: 50;
    pointer-events: none;
    mix-blend-mode: soft-light;
}

/* --- Ambient Glow --- */
.ambient-glow {
    position: fixed;
    pointer-events: none;
    z-index: 0;
    border-radius: 50%;
    filter: blur(120px);
    opacity: 0.15;
}
.glow-1 {
    width: 600px;
    height: 600px;
    background: var(--primary);
    top: -200px;
    left: -200px;
    opacity: 0.08;
}
.glow-2 {
    width: 500px;
    height: 500px;
    background: var(--primary-dim);
    bottom: 20%;
    right: -150px;
    opacity: 0.06;
}

/* --- Container --- */
.container {
    max-width: var(--container);
    margin: 0 auto;
    padding: 0 24px;
}

/* --- Navigation --- */
.nav {
    position: fixed;
    top: 0;
    left: 0;
    right: 0;
    z-index: 100;
    background: rgba(7, 7, 13, 0.8);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--border);
    transition: border-bottom-color 0.3s var(--ease-out-quad);
}

.nav-inner {
    max-width: var(--container);
    margin: 0 auto;
    padding: 0 24px;
    height: 60px;
    display: flex;
    align-items: center;
    justify-content: space-between;
}

.nav-logo {
    display: flex;
    align-items: center;
    gap: 10px;
    color: var(--text);
    font-weight: 600;
    font-size: 15px;
    transition: color 0.2s var(--ease-out-quad);
}
.nav-logo:hover { color: var(--primary-light); }

.nav-nous-logo {
    width: 22px;
    height: 22px;
    border-radius: 4px;
}

.nav-by {
    font-weight: 400;
    color: var(--text-muted);
    font-size: 13px;
}

.nav-links {
    display: flex;
    align-items: center;
    gap: 28px;
}

.nav-links a {
    color: var(--text-dim);
    font-size: 14px;
    font-weight: 500;
    display: flex;
    align-items: center;
    gap: 4px;
    transition: color 0.2s var(--ease-out-quad);
}
.nav-links a:hover { color: #fff; }

.external-icon { opacity: 0.4; }

/* --- Hamburger & Mobile Nav --- */
.nav-hamburger {
    display: none;
    background: none;
    border: none;
    cursor: pointer;
    padding: 6px;
    width: 34px;
    height: 34px;
    flex-direction: column;
    justify-content: center;
    gap: 5px;
}

.hamburger-bar {
    display: block;
    width: 20px;
    height: 2px;
    background: var(--text-dim);
    border-radius: 1px;
    transition: transform 0.25s var(--ease-out-quint), opacity 0.2s var(--ease-out-quad);
    transform-origin: center;
}

.nav-hamburger.open .hamburger-bar:nth-child(1) {
    transform: translateY(7px) rotate(45deg);
}

.nav-hamburger.open .hamburger-bar:nth-child(2) {
    opacity: 0;
}

.nav-hamburger.open .hamburger-bar:nth-child(3) {
    transform: translateY(-7px) rotate(-45deg);
}

.nav-mobile {
    display: none;
}

.nav-mobile.open {
    display: flex;
    flex-direction: column;
    position: absolute;
    top: 60px;
    left: 0;
    right: 0;
    background: rgba(7, 7, 13, 0.95);
    backdrop-filter: blur(20px);
    -webkit-backdrop-filter: blur(20px);
    border-bottom: 1px solid var(--border);
    padding: 16px 24px;
    gap: 16px;
}

.nav-mobile a {
    color: var(--text-dim);
    font-size: 15px;
    font-weight: 500;
    padding: 4px 0;
    transition: color 0.2s var(--ease-out-quad);
}

.nav-mobile a:hover {
    color: #fff;
}

/* --- Hero --- */
.hero {
    position: relative;
    z-index: 1;
    min-height: 100vh;
    display: flex;
    align-items: center;
    justify-content: center;
    padding: 120px 24px 80px;
    text-align: center;
}

.hero-content {
    max-width: 760px;
}

.hero-badge {
    display: inline-flex;
    align-items: center;
    gap: 8px;
    padding: 6px 16px;
    background: rgba(48, 80, 255, 0.08);
    border: 1px solid rgba(48, 80, 255, 0.18);
    border-radius: 100px;
    font-size: 13px;
    color: var(--text-dim);
    margin-bottom: 32px;
    font-weight: 450;
}

.badge-dot {
    width: 6px;
    height: 6px;
    border-radius: 50%;
    background: var(--primary);
    display: inline-block;
    animation: pulse-dot 2s var(--ease-in-out-quad) infinite;
}

@keyframes pulse-dot {
    0%, 100% { opacity: 1; }
    50% { opacity: 0.3; }
}

.hero-ascii {
    margin-bottom: 28px;
    font-family: 'JetBrains Mono', monospace;
    font-variant-ligatures: none;
    font-size: clamp(4px, 0.95vw, 11px);
    line-height: 1.15;
    color: var(--primary-light);
    text-align: center;
    text-shadow: 0 0 20px rgba(48, 80, 255, 0.3);
    opacity: 0.85;
    transition: opacity 0.3s var(--ease-out-cubic);
    overflow-x: auto;
    white-space: pre;
}

.hero-ascii:hover {
    opacity: 1;
}

.hero-title {
    font-size: clamp(36px, 6vw, 56px);
    font-weight: 700;
    line-height: 1.15;
    letter-spacing: -0.03em;
    margin-bottom: 20px;
    color: #fff;
}

.hero-gradient {
    background: linear-gradient(135deg, var(--primary), var(--primary-light), #90B0FF);
    -webkit-background-clip: text;
    -webkit-text-fill-color: transparent;
    background-clip: text;
}

.hero-subtitle {
    font-size: 17px;
    line-height: 1.7;
    color: var(--text-dim);
    max-width: 620px;
    margin: 0 auto 36px;
}

.hero-install {
    margin-bottom: 32px;
}

/* --- Install Widget (hero tabbed installer) --- */
.install-widget {
    max-width: 740px;
    margin: 0 auto;
    background: var(--bg-card);
    border: 1px solid var(--border);
    border-radius: var(--radius);
    overflow: hidden;
    transition: border-color 0.3s var(--ease-out-quad);
}

.install-widget:hover {
    border-color: var(--border-hover);
}

.install-widget-header {
    display: flex;
    align-items: center;
    gap: 16px;
    padding: 10px 16px;
    background: rgba(255, 255, 255, 0.02);
    border-bottom: 1px solid var(--border);
}

.install-dots {
    display: flex;
    gap: 6px;
    flex-shrink: 0;
}

.install-dots .dot {
    width: 10px;
    height: 10px;
    border-radius: 50%;
}

.install-tabs {
    display: flex;
    gap: 4px;
    flex-wrap: wrap;
}

.install-tab {
    display: inline-flex;
    align-items: center;
    gap: 6px;
    padding: 5px 14px;
    border: none;
    border-radius: 6px;
    font-family: var(--font-sans);
    font-size: 12px;
    font-weight: 500;
    cursor: pointer;
    transition: color 0.2s var(--ease-out-quad), background 0.2s var(--ease-out-quad);
    background: transparent;
    color: var(--text-muted);
}

.install-tab:hover {
    color: var(--text-dim);
    background: rgba(255, 255, 255, 0.04);
}

.install-tab.active {
    background: rgba(48, 80, 255, 0.14);
    color: var(--primary-light);
}

.install-tab svg {
    flex-shrink: 0;
}

.install-widget-body {
    display: flex;
    align-items: center;
    gap: 10px;
    padding: 14px 16px;
    font-family: var(--font-mono);
    font-size: 13px;
    color: var(--text);
    overflow-x: auto;
}

.install-prompt {
    color: var(--primary-light);
    font-weight: 600;
    flex-shrink: 0;
    opacity: 0.7;
}

.install-widget-body code {
    flex: 1;
    white-space: nowrap;
    overflow: hidden;
    text-overflow: ellipsis;
    text-align: left;
    transition: opacity 0.15s var(--ease-out-quad);
}

/* --- Code block tabs (install step section) --- */
.code-tabs {
    display: flex;
    gap: 2px;
}

.code-tab {
    padding: 3px 10px;
    border: none;
    border-radius: 4px;
    font-family: var(--font-mono);
    font-size: 11px;
    font-weight: 500
