.sidebar {
  position: sticky;
  top: 160px;
  height: calc(100vh - 160px);
  overflow-y: auto;
  padding: 1.25rem 1rem 2rem 1.5rem;
  border-right: 1px solid rgba(255, 215, 0, 0.05);
}

.sidebar::-webkit-scrollbar {
  width: 4px;
}
.sidebar::-webkit-scrollbar-thumb {
  background: rgba(255, 215, 0, 0.1);
  border-radius: 2px;
}

.sidebarHeader {
  display: flex;
  align-items: center;
  justify-content: space-between;
  margin-bottom: 0.75rem;
}

.sidebarTitle {
  font-size: 0.72rem;
  font-weight: 600;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  color: var(--ifm-font-color-secondary);
  margin: 0;
}

.sidebarClear {
  font-family: "DM Sans", sans-serif;
  font-size: 0.72rem;
  color: rgba(255, 215, 0, 0.6);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  transition: color 0.15s;
}

.sidebarClear:hover {
  color: #ffd700;
}

.catList {
  display: flex;
  flex-direction: column;
  gap: 1px;
}

.catItem {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  padding: 0.45rem 0.6rem;
  border: none;
  border-radius: 6px;
  background: transparent;
  color: var(--ifm-font-color-secondary, #9a968e);
  font-family: "DM Sans", sans-serif;
  font-size: 0.82rem;
  cursor: pointer;
  transition: all 0.15s;
  text-align: left;
  width: 100%;
}

.catItem:hover {
  background: rgba(255, 215, 0, 0.04);
  color: var(--ifm-font-color-base);
}

.catItemActive {
  background: rgba(255, 215, 0, 0.08);
  color: #ffd700;
}

.catItemIcon {
  font-size: 0.9rem;
  width: 1.3rem;
  text-align: center;
  flex-shrink: 0;
}

.catItemLabel {
  flex: 1;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
}

.catItemCount {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.68rem;
  color: rgba(255, 215, 0, 0.3);
  min-width: 1.5rem;
  text-align: right;
}

.catItemActive .catItemCount {
  color: rgba(255, 215, 0, 0.6);
}

.sidebarToggle {
  display: none;
}


.main {
  padding: 1.25rem 1.5rem 3rem;
  min-width: 0;
}

.filterSummary {
  display: flex;
  align-items: center;
  gap: 0.5rem;
  flex-wrap: wrap;
  margin-bottom: 1rem;
  padding-bottom: 0.75rem;
  border-bottom: 1px solid rgba(255, 215, 0, 0.05);
}

.filterCount {
  font-size: 0.82rem;
  font-weight: 600;
  color: var(--ifm-font-color-base);
  margin-right: 0.25rem;
}

.filterChip {
  display: inline-flex;
  align-items: center;
  gap: 0.3rem;
  padding: 0.2rem 0.5rem;
  border: 1px solid rgba(255, 215, 0, 0.15);
  border-radius: 4px;
  background: rgba(255, 215, 0, 0.04);
  color: rgba(255, 215, 0, 0.8);
  font-size: 0.75rem;
}

.filterChip button {
  background: none;
  border: none;
  color: inherit;
  cursor: pointer;
  padding: 0;
  font-size: 0.85rem;
  line-height: 1;
  opacity: 0.6;
  transition: opacity 0.15s;
}

.filterChip button:hover {
  opacity: 1;
}

.clearAllBtn {
  font-family: "DM Sans", sans-serif;
  font-size: 0.75rem;
  color: var(--ifm-font-color-secondary);
  background: none;
  border: none;
  cursor: pointer;
  padding: 0;
  margin-left: auto;
  transition: color 0.15s;
}

.clearAllBtn:hover {
  color: #ffd700;
}


.grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(340px, 1fr));
  gap: 0.75rem;
}


@keyframes cardIn {
  from {
    opacity: 0;
    transform: translateY(8px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.card {
  position: relative;
  border: 1px solid rgba(255, 255, 255, 0.05);
  border-radius: 10px;
  overflow: hidden;
  cursor: pointer;
  transition: border-color 0.2s, box-shadow 0.2s, transform 0.2s;
  animation: cardIn 0.35s ease both;
}

[data-theme="dark"] .card {
  background: #0c0c16;
}

.card:hover {
  border-color: rgba(255, 215, 0, 0.15);
  box-shadow: 0 4px 24px rgba(0, 0, 0, 0.3), 0 0 0 1px rgba(255, 215, 0, 0.05);
  transform: translateY(-1px);
}

.cardExpanded {
  border-color: rgba(255, 215, 0, 0.2);
  box-shadow: 0 8px 32px rgba(0, 0, 0, 0.4), 0 0 0 1px rgba(255, 215, 0, 0.08);
}

.cardAccent {
  position: absolute;
  top: 0;
  left: 0;
  width: 3px;
  height: 100%;
  opacity: 0.5;
  transition: opacity 0.2s;
}

.card:hover .cardAccent {
  opacity: 1;
}

.cardInner {
  padding: 1rem 1rem 0.85rem 1.15rem;
}

.cardTop {
  display: flex;
  align-items: flex-start;
  gap: 0.6rem;
  margin-bottom: 0.5rem;
}

.cardIcon {
  font-size: 1.15rem;
  line-height: 1;
  flex-shrink: 0;
  margin-top: 0.1rem;
  opacity: 0.7;
}

.cardTitleGroup {
  display: flex;
  align-items: flex-start;
  justify-content: space-between;
  gap: 0.5rem;
  flex: 1;
  min-width: 0;
}

.cardTitle {
  font-size: 0.92rem;
  font-weight: 600;
  line-height: 1.3;
  margin: 0;
  word-break: break-word;
  color: var(--ifm-font-color-base);
}

.sourcePill {
  display: inline-flex;
  align-items: center;
  gap: 0.25rem;
  font-family: "JetBrains Mono", monospace;
  font-size: 0.62rem;
  font-weight: 500;
  padding: 0.15rem 0.45rem;
  border-radius: 4px;
  border: 1px solid;
  white-space: nowrap;
  flex-shrink: 0;
  margin-top: 0.1rem;
}

.cardDesc {
  font-size: 0.82rem;
  line-height: 1.55;
  color: var(--ifm-font-color-secondary, #9a968e);
  margin: 0 0 0.6rem;
  display: -webkit-box;
  -webkit-line-clamp: 2;
  -webkit-box-orient: vertical;
  overflow: hidden;
}

.cardDescFull {
  -webkit-line-clamp: unset;
}

.cardMeta {
  display: flex;
  align-items: center;
  gap: 0.35rem;
  flex-wrap: wrap;
}

.catButton {
  font-family: "JetBrains Mono", monospace;
  font-size: 0.66rem;
  padding: 0.15rem 0.45rem;
  border: 1px solid rgba(255, 215, 0, 0.12);
  border-radius: 3px;
  background: rgba(255, 215, 0, 0.04);
  color: rgba(255, 215, 0, 0.7);
  cursor: pointer;
  transition: all 0.
