        else:
            result.append(c)
    return ''.join(result)

def _apply_bubble(word):
    """Bubble — circled letter Unicode characters."""
    result = []
    for c in word:
        code = ord(c.lower())
        if 97 <= code <= 122:
            result.append(chr(0x24D0 + code - 97))
        else:
